import {cleanPoint,samePoint,nearestVertex,nearestWall,moveVertex,splitWall,wallVertices} from './wall-geometry.mjs';
import {gridPosition} from './grid-view.mjs';
export function createWallEditor({state,commit,change}) {
  let mode='',anchor=null,hover=null,drag=null,preview=null,selection=null,busy=false,scope='',undo=[],redo=[];
  const data=()=>state().battle.wallData ?? state().map.wallData ?? {manual:true,walls:[],doors:[]};
  const clone=x=>structuredClone(x);
  function reset(){anchor=hover=drag=preview=selection=null;}
  function sync(){const s=state(),key=s.scope;if(scope!==key){scope=key;mode='';reset();undo=[];redo=[];}}
  function setMode(value){sync();mode=value;reset();change();}
  async function save(next,record=true,original){if(busy)return false;const before=clone(original??data());next.manual=true;busy=true;change();try {const ok=await commit(before,next);if(ok && record){undo.push({before,after:clone(next)});redo=[];}return ok;} finally {busy=false;change();}}
  function position(e){const {map,surface}=state(),p=gridPosition(map,surface,e),rect=surface.getBoundingClientRect();const sx=rect.width/map.width*(map.cellWidth??map.size),sy=rect.height/map.height*(map.cellHeight??map.size);const raw=cleanPoint({x:Math.max(0,Math.min(map.cols,p.gx)),y:Math.max(0,Math.min(map.rows,p.gy))});const snap=e.altKey ? null : nearestVertex(data(),raw,sx,sy,12,drag?.from);return {point:snap??raw,snap,raw,sx,sy};}
  const onGrid=e=>e.target?.id==='play-grid';
  document.addEventListener('pointerdown',e=>{sync();if(!mode || !onGrid(e) || e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();if(busy)return;const p=position(e);hover=p;
    if(mode==='edit'){const vertex=nearestVertex(data(),p.raw,p.sx,p.sy);if(vertex){drag={from:vertex,to:vertex,pointer:e.pointerId,before:clone(data())};preview=clone(data());}else selection=nearestWall(data(),p.raw,p.sx,p.sy);change();}
  },true);
  document.addEventListener('pointermove',e=>{if(!mode || (!onGrid(e) && !drag))return;if(drag){e.preventDefault();e.stopImmediatePropagation();}const p=position(e);hover=p;if(drag){drag.to=p.point;preview=moveVertex(clone(drag.before),drag.from,p.point);}change();},true);
  document.addEventListener('pointerup',async e=>{if(!drag || e.pointerId!==drag.pointer)return;e.preventDefault();e.stopImmediatePropagation();const next=preview,before=drag.before,changed=!samePoint(drag.from,drag.to);drag=preview=null;if(changed)await save(next,true,before);change();},true);
  document.addEventListener('pointercancel',()=>{drag=preview=null;change();},true);
  document.addEventListener('click',async e=>{if(!mode || !onGrid(e))return;e.preventDefault();e.stopImmediatePropagation();if(busy || mode==='edit')return;const p=position(e);
    if(mode==='delete'){const found=nearestWall(data(),p.raw,p.sx,p.sy);if(found){const next=clone(data());next[found.type].splice(found.index,1);await save(next);}return;}
    if(!anchor){anchor=p.point;change();return;}
    if(samePoint(anchor,p.point))return;const next=clone(data()),type=mode==='door'?'doors':'walls';next[type]??=[];next[type].push({x1:anchor.x,y1:anchor.y,x2:p.point.x,y2:p.point.y,...(type==='doors'?{id:crypto.randomUUID(),state:'closed'}:{})});if(await save(next))anchor=p.snap?null:p.point;change();
  },true);
  document.addEventListener('dblclick',e=>{if(mode && onGrid(e)){e.preventDefault();e.stopImmediatePropagation();anchor=null;change();}},true);
  document.addEventListener('contextmenu',e=>{if(mode && onGrid(e)){e.preventDefault();anchor=null;drag=preview=null;change();}},true);
  document.addEventListener('keydown',e=>{if(!mode || e.target.closest?.('input,select,textarea,[contenteditable=true]'))return;if(['Escape','Enter','Delete','Backspace'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key==='Delete' || e.key==='Backspace')void action('delete');else {anchor=null;drag=preview=null;change();}}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.stopImmediatePropagation();}},true);
  async function action(name){if(busy)return;if(['draw','edit','door','delete-mode'].includes(name)){setMode(name==='delete-mode'?'delete':name);return;}if(name==='done'){setMode('');return;}if(name==='finish'){anchor=null;change();return;}if(selection && JSON.stringify(data()[selection.type]?.[selection.index])!==JSON.stringify(selection.segment)){selection=null;change();return;}if(name==='split' && selection){const next=clone(data());splitWall(next,selection);selection=null;await save(next);}if(name==='delete' && selection){const next=clone(data());next[selection.type].splice(selection.index,1);selection=null;await save(next);}if(name==='undo' || name==='redo'){const from=name==='undo'?undo:redo,to=name==='undo'?redo:undo,item=from.at(-1);if(!item)return;const expected=name==='undo'?item.after:item.before;if(JSON.stringify(data())!==JSON.stringify(expected)){undo=[];redo=[];change();return;}if(await save(clone(name==='undo'?item.before:item.after),false)){from.pop();to.push(item);anchor=null;change();}}}
  function toolbar(){sync();if(!mode)return '';const button=(name,label,disabled=false)=>`<button type="button" data-wall-editor="${name}" ${disabled||busy?'disabled':''} aria-pressed="${mode===(name==='delete-mode'?'delete':name)}">${label}</button>`;return `<div class="wall-editor-bar" role="toolbar" aria-label="Wall editor"><strong>Walls · map revealed only for you</strong><div>${button('draw','Draw')}${button('edit','Edit')}${button('door','Door')}${button('delete-mode','Erase')}${button('finish','Finish chain',!anchor)}${button('split','Add vertex',!selection)}${button('delete','Delete selected',!selection)}${button('undo','Undo',!undo.length)}${button('redo','Redo',!redo.length)}${button('done','Done')}</div><small>${busy?'Saving walls…':mode==='edit'?'Drag a vertex. Click a line to select it.':mode==='delete'?'Click a segment to erase it.':'Click points to draw. Escape / right-click finishes. Snap: nearby vertices; Alt bypasses.'} Middle-drag to pan.</small></div>`;}
  function draw(c,map,scaleX,scaleY){if(!mode)return;const cw=map.cellWidth??map.size,ch=map.cellHeight??map.size,ox=map.offsetX??0,oy=map.offsetY??0;const p=v=>[ox+v.x*cw,oy+v.y*ch];c.save();c.lineWidth=3/scaleX;for(const [type,segments] of [['walls',(preview??data()).walls??[]],['doors',(preview??data()).doors??[]]])for(const s of segments){c.strokeStyle=type==='doors'?'#f5b54c':'#75e2df';c.beginPath();c.moveTo(...p({x:s.x1,y:s.y1}));c.lineTo(...p({x:s.x2,y:s.y2}));c.stroke();}if(anchor&&hover){c.strokeStyle='#fff3a0';c.setLineDash([6/scaleX,4/scaleX]);c.beginPath();c.moveTo(...p(anchor));c.lineTo(...p(hover.point));c.stroke();c.setLineDash([]);}for(const v of wallVertices(preview??data())){c.beginPath();c.ellipse(...p(v),5/scaleX,5/scaleY,0,0,Math.PI*2);c.fillStyle='#10292b';c.fill();c.strokeStyle='#a5ffed';c.stroke();}if(hover?.snap){c.beginPath();c.ellipse(...p(hover.snap),9/scaleX,9/scaleY,0,0,Math.PI*2);c.strokeStyle='#fff3a0';c.stroke();}if(selection){c.strokeStyle='#fff3a0';c.lineWidth=5/scaleX;c.beginPath();c.moveTo(...p({x:selection.segment.x1,y:selection.segment.y1}));c.lineTo(...p({x:selection.segment.x2,y:selection.segment.y2}));c.stroke();}c.restore();}
  return {setMode,action,toolbar,draw,get active(){sync();return Boolean(mode);}};
}
